package main

import (
	"fmt"
)

type Item struct {
	Name  string
	Price float64
	Qty   int
}

func total(items []Item) float64 {
	sum := 0.0
	for i := 0; i < len(items); i++ {
		sum += items[i].Price * float64(items[i].Qty)
	}
	return sum
}

func main() {
	items := []Item{{"pen", 2.5, 4}, {"book", 10, 1}}
	fmt.Printf("Total: %.2f\n", total(items))
}
